class UpdateTests {
 static int passed;static RSACryptoServiceProvider signer;static string modulus,exponent;
 static void Check(bool value,string name){if(!value)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}
 delegate void TestAction();static void Reject(TestAction action,string name){bool failed=false;try{action();}catch(Exception){failed=true;}Check(failed,name);}
 static byte[] Envelope(string payload){byte[] body=Encoding.UTF8.GetBytes(payload);return Encoding.UTF8.GetBytes("{\"payload\":\""+Convert.ToBase64String(body)+"\",\"signature\":\""+Convert.ToBase64String(signer.SignData(body,CryptoConfig.MapNameToOID("SHA256")))+"\"}");}
 static string Row(int code,string name,long size,string hash,string url){return "{\"id\":\"windows\",\"versionCode\":"+code+",\"versionName\":\""+name+"\",\"size\":"+size+",\"sha256\":\""+hash+"\",\"url\":\""+url+"\"}";}
