 sealed class FileRow {internal string Name;internal byte[] Bytes;internal FileRow(string name,byte[] bytes){Name=name;Bytes=bytes;}}
 static uint Crc(byte[] bytes){uint value=0xffffffff;foreach(byte b in bytes){value^=b;for(int i=0;i<8;i++)value=(value&1)!=0?(value>>1)^0xedb88320:value>>1;}return ~value;}
 static byte[] Zip(params FileRow[] rows){using(MemoryStream data=new MemoryStream()){BinaryWriter w=new BinaryWriter(data);List<uint> offsets=new List<uint>();foreach(FileRow row in rows){offsets.Add((uint)data.Position);byte[] name=Encoding.UTF8.GetBytes(row.Name);w.Write(0x04034b50);w.Write((ushort)20);w.Write((ushort)0x800);w.Write((ushort)0);w.Write(0);w.Write(Crc(row.Bytes));w.Write(row.Bytes.Length);w.Write(row.Bytes.Length);w.Write((ushort)name.Length);w.Write((ushort)0);w.Write(name);w.Write(row.Bytes);}uint directory=(uint)data.Position;for(int i=0;i<rows.Length;i++){FileRow row=rows[i];byte[] name=Encoding.UTF8.GetBytes(row.Name);w.Write(0x02014b50);w.Write((ushort)20);w.Write((ushort)20);w.Write((ushort)0x800);w.Write((ushort)0);w.Write(0);w.Write(Crc(row.Bytes));w.Write(row.Bytes.Length);w.Write(row.Bytes.Length);w.Write((ushort)name.Length);w.Write((ushort)0);w.Write((ushort)0);w.Write((ushort)0);w.Write((ushort)0);w.Write(0);w.Write(offsets[i]);w.Write(name);}uint length=(uint)data.Position-directory;w.Write(0x06054b50);w.Write((ushort)0);w.Write((ushort)0);w.Write((ushort)rows.Length);w.Write((ushort)rows.Length);w.Write(length);w.Write(directory);w.Write((ushort)0);w.Flush();return data.ToArray();}}
 static FileRow F(string name){return new FileRow(name,Encoding.UTF8.GetBytes("test bytes"));}
