 static int Main(string[] args){string root=Path.Combine(Path.GetTempPath(),"USBBridge-UpdateTests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{signer=new RSACryptoServiceProvider(2048,new CspParameters(24));signer.PersistKeyInCsp=false;RSAParameters key=signer.ExportParameters(false);modulus=Convert.ToBase64String(key.Modulus);exponent=Convert.ToBase64String(key.Exponent);string hash=new string('a',64),row=Row(159,"0.15.9",100,hash,Asset),payload=Payload(row);UpdateRelease valid=Parse(payload);Check(valid.Code==159&&valid.Name=="0.15.9"&&valid.Sequence==156,"signed manifest accepted with pinned key");Check(UpdateClient.ShouldOffer(valid),"newer numeric and display version offered");Check(!UpdateClient.ShouldOffer(Parse(Payload(Row(158,"0.15.8",100,hash,Asset)))),"current version158 never offers itself");Check(!UpdateClient.ShouldOffer(Parse(Payload(Row(154,"0.15.4",100,hash,Asset)))),"older version never offered");Reject(delegate{Parse(Payload(Row(159,"0.15.4",100,hash,Asset)));},"higher code cannot disguise a display-version downgrade");byte[] envelope=Envelope(payload);envelope[20]^=1;Reject(delegate{UpdateManifest.Read(envelope,modulus,exponent);},"modified signed payload rejected");byte[] badSignature=Envelope(payload);string raw=Encoding.UTF8.GetString(badSignature);int signatureAt=raw.IndexOf("\"signature\":\"")+13;char[] changed=raw.ToCharArray();changed[signatureAt]=changed[signatureAt]=='A'?'B':'A';Reject(delegate{UpdateManifest.Read(Encoding.UTF8.GetBytes(changed),modulus,exponent);},"modified signature rejected");Reject(delegate{UpdateManifest.Read(Envelope(payload),UpdateManifest.PublicModulus,UpdateManifest.PublicExponent);},"different signing key rejected");Reject(delegate{Parse(payload.Replace("\"schema\":1","\"schema\":2"));},"unknown schema rejected");Reject(delegate{Parse(payload.Replace("\"sequence\":156","\"sequence\":-1"));},"negative release sequence rejected");Reject(delegate{Parse(payload.Replace("\"sequence\":156","\"sequence\":156,\"sequence\":158"));},"duplicate signed keys rejected");Reject(delegate{Parse(Payload(row+","+row));},"duplicate Windows artifact rejected");Reject(delegate{Parse(Payload(Row(159,"0.15.9",0,hash,Asset)));},"zero download size rejected");Reject(delegate{Parse(Payload(Row(159,"0.15.9",UpdateManifest.MaxAssetBytes+1,hash,Asset)));},"oversized download rejected");Reject(delegate{Parse(Payload(Row(159,"0.15.9",100,"invalid",Asset)));},"invalid asset digest rejected");Reject(delegate{Parse(Payload(Row(159,"version x",100,hash,Asset)));},"invalid display version rejected");Reject(delegate{UpdateJson.Parse("{\"x\":1,\"x\":2}");},"JSON duplicate envelope keys rejected");Reject(delegate{UpdateJson.Parse("{}{}");},"JSON trailing data rejected");Reject(delegate{UpdateJson.Parse("[1.5]");},"unexpected decimal manifest numbers rejected");Reject(delegate{UpdateJson.Parse(new string('[',14)+"0"+new string(']',14));},"nested manifest complexity bounded");Reject(delegate{UpdateJson.Parse(new string(' ',196609));},"manifest text size bounded");Check(Parse("{\"schema\":1,\"sequence\":156,\"releases\":[]}")==null,"missing Windows release gives no offer");Check(!UpdateManifest.IsAssetUrl(Asset.Replace("https:","http:")),"HTTP asset rejected");Check(!UpdateManifest.IsAssetUrl(Asset.Replace("github.com","example.com")),"foreign asset host rejected");Check(!UpdateManifest.IsAssetUrl(Asset+"?token=bad"),"asset query credential channel rejected");Check(!UpdateManifest.IsAssetUrl(Asset.Replace("github.com/","user@github.com/")),"URL credentials rejected");Check(!UpdateManifest.IsDownloadHost(new Uri("http://release-assets.githubusercontent.com/file")),"redirect TLS downgrade rejected");Check(!UpdateManifest.IsDownloadHost(new Uri("https://github.com.attacker.invalid/file")),"lookalike redirect host rejected");Check(UpdateClient.NextDelay(0,0)==30000&&UpdateClient.NextDelay(0,3000)==33000,"healthy polling stays thirty seconds with bounded jitter");Check(UpdateClient.NextDelay(6,99999)==303000,"network errors back off with bounded ceiling");
 foreach(string unsafeName in new string[]{"../outside.exe","/outside.exe","C:/outside.exe","helper\\outside.exe","helper/../outside.exe","CON.txt","x./a","x /a","helper//a"}){string name=unsafeName;Reject(delegate{SafeUpdateZip.ValidateName(name);},"ZIP rejects "+name);}SafeUpdateZip.ValidateName("platform-tools/AdbWinApi.dll");Check(true,"normal bundled driverless runtime path accepted");
 byte[] good=Zip(F("USBBridge.exe"),F("USBBridge.exe.config"),F("helper/server.jar"));string zip=Save(root,"good.zip",good),outPath=Path.Combine(root,"extracted");Directory.CreateDirectory(outPath);SafeUpdateZip.Extract(zip,outPath);SafeUpdateZip.VerifyInstalled(zip,outPath);Check(File.Exists(Path.Combine(outPath,"helper/server.jar")),"safe ZIP extracted and all installed bytes verified");File.AppendAllText(Path.Combine(outPath,"USBBridge.exe"),"tampered");Reject(delegate{SafeUpdateZip.VerifyInstalled(zip,outPath);},"modified installed executable rejected");string dup=Save(root,"duplicate.zip",Zip(F("USBBridge.exe"),F("USBBridge.exe.config"),F("USBBRIDGE.EXE")));Reject(delegate{SafeUpdateZip.Extract(dup,Path.Combine(root,"dup"));},"case-insensitive duplicate archive entry rejected");string traverse=Save(root,"traverse.zip",Zip(F("USBBridge.exe"),F("USBBridge.exe.config"),F("../escape")));Reject(delegate{SafeUpdateZip.Extract(traverse,Path.Combine(root,"escape"));},"archive traversal blocked before creating files");Check(!File.Exists(Path.Combine(root,"escape")),"bad archive creates no installation folder");byte[] corrupt=(byte[])good.Clone();corrupt[43]^=1;string corruptPath=Save(root,"corrupt.zip",corrupt);Reject(delegate{SafeUpdateZip.Extract(corruptPath,Path.Combine(root,"corrupt"));},"corrupt archive data rejected");
 if(args.Length==1){byte[] app=File.ReadAllBytes(args[0]);byte[] package=Zip(new FileRow("USBBridge.exe",app),new FileRow("USBBridge.exe.config",Encoding.UTF8.GetBytes("<configuration/>")));string packagePath=Save(root,"actual.zip",package);UpdateRelease install=Parse(Payload(Row(158,"0.15.8",package.Length,UpdateManifest.Hash(package),CurrentAsset)));string installRoot=Path.Combine(root,"installed");string installed=UpdateInstaller.Prepare(installRoot,install,packagePath);UpdateInstaller.ValidateInstalled(installed,install);Check(!File.Exists(Path.Combine(installRoot,"latest.manifest")),"download and extraction do not redirect existing shortcuts");Check(UpdateInstaller.ConfirmInstallation(installRoot,Path.Combine(installed,"USBBridge.exe"),158,"0.15.8",modulus,exponent),"shown child can confirm its own validated installation");Check(UpdateManifest.Read(File.ReadAllBytes(Path.Combine(installRoot,"latest.manifest")),modulus,exponent).Code==158,"committed pointer retains signed manifest identity");Reject(delegate{UpdateInstaller.ConfirmInstallation(installRoot,Path.Combine(installed,"USBBridge.exe"),159,"0.15.9",modulus,exponent);},"different child version cannot confirm the installation");Check(File.Exists(Path.Combine(installed,"release.manifest")),"real version158 installs in a separate verified directory");Check(File.Exists(packagePath)&&File.Exists(args[0]),"portable source copy and downloaded archive remain intact");string repeated=UpdateInstaller.Prepare(installRoot,install,packagePath);Check(repeated==installed,"interrupted install can reuse the complete verified version");UpdateRelease wrong=Parse(Payload(Row(159,"0.15.9",package.Length,UpdateManifest.Hash(package),Asset)));Reject(delegate{UpdateInstaller.Prepare(installRoot,wrong,packagePath);},"manifest version cannot install an older executable");install.Sha256=new string('0',64);Reject(delegate{UpdateInstaller.Prepare(installRoot,install,packagePath);},"bad archive hash never changes installation");}
 Console.WriteLine("TOTAL "+passed+" passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{if(signer!=null)((IDisposable)signer).Dispose();try{Directory.Delete(root,true);}catch{}}}
}
